    json bj = Bucket{"my-bucket", {0.5f, 0.8f}};
    ASSERT_EQ("my-bucket", bj["name"]);
    ASSERT_TRUE(bj["partition_points"].is_array());
    ASSERT_EQ(0.5f, bj["partition_points"][0]);
    ASSERT_EQ(0.8f, bj["partition_points"][1]);
}

